// Literal full-grid quotient C/F_0, restricted to Maslov -1,0,1 for H_0.
#include <algorithm>
#include <cassert>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <map>
#include <string>
#include <unordered_map>
#include <vector>
#include <sys/resource.h>
using namespace std;using U=uint32_t;using L=uint64_t;template<class T>void wr(ofstream&f,T x){f.write((char*)&x,sizeof x);}int main(int argc,char**argv){rlimit lim{6ULL<<30,6ULL<<30};assert(!setrlimit(RLIMIT_AS,&lim));assert(argc==3);ifstream in(argv[1]);string pre=argv[2];int n;in>>n;assert(n>=2&&n<=15);vector<int>O(n),X(n);for(int&i:O)in>>i;for(int&i:X)in>>i;assert(in);int oo=0,xx=0;for(int r=0;r<n;r++)for(int s=r+1;s<n;s++){oo+=O[r]<O[s];xx+=X[r]<X[s];}vector<vector<int>>wm(n,vector<int>(n)),wa=wm;for(int r=0;r<n;r++)for(int c=0;c<n;c++)for(int k=0;k<n;k++){wm[r][c]-=(k>=r?c<=O[k]:O[k]<c);wa[r][c]+=(k>=r?int(c<=X[k])-int(c<=O[k]):int(X[k]<c)-int(O[k]<c));}U full=(1U<<n)-1;vector<int>lo(full+1,99999),hi(full+1,-99999),amax(full+1,-99999);lo[full]=hi[full]=amax[full]=0;for(int mask=(int)full-1;mask>=0;mask--){int r=__builtin_popcount((U)mask);for(int c=0;c<n;c++)if(!(mask>>c&1)){int d=wm[r][c]+__builtin_popcount((U)mask&((1U<<c)-1));lo[mask]=min(lo[mask],d+lo[mask|(1U<<c)]);hi[mask]=max(hi[mask],d+hi[mask|(1U<<c)]);amax[mask]=max(amax[mask],wa[r][c]+amax[mask|(1U<<c)]);}}
vector<L>S;vector<int8_t>M,A;auto rec=[&](auto&&self,U mask,int m,int a,L code)->void{if(m+lo[mask]>1||m+hi[mask]<-1||a+amax[mask]<2)return;if(mask==full){assert(m>=-1&&m<=1&&a>=2&&a%2==0);S.push_back(code);M.push_back(m);A.push_back(a/2);return;}int r=__builtin_popcount(mask);for(int c=0;c<n;c++)if(!(mask>>c&1)){int d=wm[r][c]+__builtin_popcount(mask&((1U<<c)-1));self(self,mask|(1U<<c),m+d,a+wa[r][c],code|((L)c<<(4*r)));}};rec(rec,0,oo+1,oo-xx-n+1,0);U N=S.size();cerr<<"NEW quotient inventory "<<pre<<" states="<<N<<"\n";assert(N<2000000);unordered_map<L,U>idx;idx.reserve(N*1.3);for(U i=0;i<N;i++)assert(idx.emplace(S[i],i).second);
vector<vector<U>>D(N);vector<int>p(n);L orbits=0,positiveX=0,edges=0;for(U i=0;i<N;i++){if(M[i]==-1)continue;L code=S[i];for(int r=0;r<n;r++)p[r]=(code>>(4*r))&15;vector<U>terms;for(int r=0;r<n;r++)for(int s=0;s<n;s++)if(r!=s){int h=(s-r+n)%n,w=(p[s]-p[r]+n)%n;bool empty=true;for(int k=0;k<n;k++)if((k-r+n)%n<h&&(O[k]-p[r]+n)%n<w){empty=false;break;}if(!empty)continue;for(int k=0;k<n;k++){int dr=(k-r+n)%n,dc=(p[k]-p[r]+n)%n;if(dr>0&&dr<h&&dc>0&&dc<w){empty=false;break;}}if(!empty)continue;int nx=0;for(int k=0;k<n;k++)if((k-r+n)%n<h&&(X[k]-p[r]+n)%n<w)nx++;if(A[i]-nx<=0)continue;L q=code^((L)(p[r]^p[s])<<(4*r))^((L)(p[r]^p[s])<<(4*s));auto it=idx.find(q);assert(it!=idx.end());U j=it->second;assert(M[j]==M[i]-1&&A[i]-A[j]==nx);terms.push_back(j);orbits++;positiveX+=nx>0;}sort(terms.begin(),terms.end());for(size_t k=0;k<terms.size();){size_t j=k+1;while(j<terms.size()&&terms[j]==terms[k])j++;if((j-k)%2)D[i].push_back(terms[k]);k=j;}edges+=D[i].size();}vector<U>stamp(N);vector<unsigned char>par(N);vector<U>touched;for(U i=0;i<N;i++)if(M[i]==1){touched.clear();for(U j:D[i])for(U v:D[j]){if(stamp[v]!=i+1){stamp[v]=i+1;par[v]=0;touched.push_back(v);}par[v]^=1;}for(U v:touched)assert(!par[v]);}
map<int,L>dims,ranks;map<pair<int,int>,L>bigdims;for(U i=0;i<N;i++){dims[M[i]]++;bigdims[{M[i],A[i]}]++;}ofstream trace(pre+".rank-trace",ios::binary);wr(trace,N);for(int m:{0,1}){vector<int>row(N,-1);U count=0;for(U i=0;i<N;i++)if(M[i]==m-1)row[i]=count++;vector<vector<L>>basis(count);vector<int>owner(count,-1);L rank=0,xors=0;wr(trace,m);for(U i=0;i<N;i++)if(M[i]==m){vector<L>v((count+63)/64);for(U j:D[i]){assert(row[j]>=0);v[row[j]/64]^=1ULL<<(row[j]%64);}while(!v.empty()&&!v.back())v.pop_back();vector<U>ops;while(!v.empty()){U p=(v.size()-1)*64+63-__builtin_clzll(v.back());if(basis[p].empty()){basis[p]=move(v);owner[p]=i;rank++;break;}ops.push_back(owner[p]);for(size_t k=0;k<basis[p].size();k++)v[k]^=basis[p][k];while(!v.empty()&&!v.back())v.pop_back();xors++;}wr(trace,i);wr(trace,(U)ops.size());trace.write((char*)ops.data(),4ULL*ops.size());}ranks[m]=rank;cerr<<"rank d"<<m<<"="<<rank<<" xors="<<xors<<"\n";}
L h0=dims[0]-ranks[0]-ranks[1];assert(h0==0);ofstream out(pre+".json");out<<"{\"scope\":\"actual full positive-X quotient C/F0, Maslov -1,0,1\",\"n\":"<<n<<",\"state_count\":"<<N<<",\"rectangle_orbits\":"<<orbits<<",\"positive_X_orbits\":"<<positiveX<<",\"F2_edges\":"<<edges<<",\"d0_rank\":"<<ranks[0]<<",\"d1_rank\":"<<ranks[1]<<",\"H0_dimension\":0,\"actual_square_zero\":true,\"bigraded_chain_dimensions\":[";bool first=true;for(auto [g,c]:bigdims){if(!first)out<<",";first=false;out<<"["<<g.first<<","<<g.second<<","<<c<<"]";}out<<"],\"states\":[";for(U i=0;i<N;i++){if(i)out<<",";out<<"["<<S[i]<<","<<(int)M[i]<<","<<(int)A[i]<<"]";}out<<"],\"columns\":[";for(U i=0;i<N;i++){if(i)out<<",";out<<"[";for(U j=0;j<D[i].size();j++){if(j)out<<",";out<<D[i][j];}out<<"]";}out<<"]}\n";cerr<<"QUOTIENT H0=0 PASS\n";
}
